package com.linkplay.app;
import android.graphics.Color; import android.os.Bundle; import android.view.Gravity; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import androidx.media3.common.*; import androidx.media3.exoplayer.ExoPlayer; import androidx.media3.ui.PlayerView;
public class PlayerActivity extends AppCompatActivity {ExoPlayer player; public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xFF07111F);getWindow().setNavigationBarColor(0xFF07111F);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setGravity(Gravity.CENTER);root.setBackgroundColor(0xFF07111F);PlayerView view=new PlayerView(this);view.setUseController(true);root.addView(view,new LinearLayout.LayoutParams(-1,0,1));TextView msg=new TextView(this);msg.setTextColor(Color.WHITE);msg.setTextSize(14);msg.setGravity(Gravity.CENTER);msg.setPadding(24,12,24,20);root.addView(msg,new LinearLayout.LayoutParams(-1,-2));setContentView(root);String url=getIntent().getStringExtra("url");if(url==null){msg.setText("الرابط غير موجود.");return;}player=new ExoPlayer.Builder(this).build();view.setPlayer(player);player.addListener(new Player.Listener(){public void onPlayerError(PlaybackException e){msg.setText("تعذّر تشغيل الفيديو مباشرة. قد يكون الخادم يفرض التنزيل أو لا يدعم البث. جرّب المشغّل الخارجي.");}});player.setMediaItem(MediaItem.fromUri(url));player.prepare();player.play();}protected void onStop(){super.onStop();if(player!=null){player.release();player=null;}}}
